(()=>{
'use strict';
const D=window.SKY_COMPETITION_DATA;if(!D)return;
Object.entries(D.verifiedTopics||{}).forEach(([topic,r])=>{
 if(!r||!/^CORE READY$/i.test(r.status||''))return;
 r.homework=[`${topic}: अपनी भाषा में 5–8 line concept summary लिखें.`,`${topic}: 5 key points/formula/rules revise करें.`,`${topic}: 3 application/exam-style questions attempt करें.`,`${topic}: आज की common mistake/trap का correction note बनाएं.`];
 r.dpp=[`${topic} — Q1: definition/core idea recall.`,`${topic} — Q2: 3 key points/rules लिखें.`,`${topic} — Q3: simple example/application.`,`${topic} — Q4: medium exam-style application.`,`${topic} — Q5: common mistake identify/correct.`,`${topic} — Q6: compare with a related concept.`,`${topic} — Q7: one statement-based check.`,`${topic} — Q8: one timed question/activity.`,`${topic} — Q9: one trap/exception check.`,`${topic} — Q10: 30-second rapid revision.`];
 r.oneLine=r.oneLine?.length?r.oneLine:[`${topic}: definition → key points → example → exam application.`];
 if(!r.memoryTip)r.memoryTip=`${topic}: D-K-E-T = Definition → Key points → Example → Trap`;
});
})();
